mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  vec3 q = p - vec3(0.0, 0.0, 4.0);
  vec3 b = abs(q) - vec3(0.3, 1.8, 0.3);
  float obelisk = max(b.x, max(b.y, b.z));
  float sea = p.y + 0.5 + 0.03 * sin(p.x * 2.0 + time) * cos(p.z * 2.0);
  return min(obelisk, sea);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.8, -3.5);
  vec3 rd = normalize(vec3(p, 1.5));
  rd.yz = rot(-0.15) * rd.yz;
  float t = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 12.0) break;
    t += d * 0.8;
  }
  vec3 col = mix(vec3(0.6, 0.1, 0.05), vec3(0.02, 0.01, 0.04), clamp(rd.y * 2.0 + 0.3, 0.0, 1.0));
  if (t < 12.0) {
    vec3 pos = ro + rd * t;
    float fog = 1.0 / (1.0 + t * t * 0.02);
    col = mix(col, vec3(0.03, 0.01, 0.02), fog);
  }
  ret = col;
}
